// Generates the copy tables of the pregnancy tools from the React sources:
//   scripts/i18n/maternity36-copy.json   (maternityText, every key)   → lib/features/tools/maternity/maternity_copy.g.dart
//   src/data/maternity-regional.json     (country input + sources, reviewedAt)        (same file)
//   scripts/i18n/followup36-copy.json    (followupText names_* / maternity_* keys)     (same file)
// Run from the repository root:  node app/test/features/tools/maternity/gen_pregnancy_copy.mjs
// (maternity_copy_test.dart fails when the generated file drifts from these sources.)
import fs from 'node:fs';
import path from 'node:path';

const root = process.cwd();
const json = (p) => JSON.parse(fs.readFileSync(path.join(root, p), 'utf8'));
const s = (v) => JSON.stringify(v).replace(/\$/g, '\\$');

const maternity = json('scripts/i18n/maternity36-copy.json').languages;
const followup = json('scripts/i18n/followup36-copy.json').languages;
const policy = json('src/data/maternity-regional.json');
const followupKeys = Object.keys(followup.en).filter((k) => /^(names_|maternity_)/.test(k));

const out = [
  '// Ported from: scripts/i18n/maternity36-copy.json (maternityText), scripts/i18n/followup36-copy.json',
  '//              (followupText names_* / maternity_*), src/data/maternity-regional.json (input, sources, reviewedAt)',
  '// GENERATED by app/test/features/tools/maternity/gen_pregnancy_copy.mjs. Do not edit by hand.',
  '// ignore_for_file: prefer_single_quotes, lines_longer_than_80_chars',
  '',
  '/// maternity36-copy.json `languages`.',
  'const Map<String, Map<String, String>> kMaternityCopy = {',
];
for (const [lang, values] of Object.entries(maternity)) {
  out.push(`  ${s(lang)}: {`);
  for (const [k, v] of Object.entries(values)) if (typeof v === 'string') out.push(`    ${s(k)}: ${s(v)},`);
  out.push('  },');
}
out.push('};', '', '/// followup36-copy.json `languages` (names_* / maternity_* keys).', 'const Map<String, Map<String, String>> kPregnancyFollowupCopy = {');
for (const [lang, values] of Object.entries(followup)) {
  const keys = followupKeys.filter((k) => typeof values[k] === 'string');
  if (!keys.length) continue;
  out.push(`  ${s(lang)}: {`);
  for (const k of keys) out.push(`    ${s(k)}: ${s(values[k])},`);
  out.push('  },');
}
out.push('};', '', `/// maternityPolicy.reviewedAt.`, `const String kMaternityReviewedAt = ${s(policy.reviewedAt)};`, '');
out.push('/// maternityPolicy.countries[code].input.', 'const Map<String, String> kMaternityCountryInput = {');
for (const [code, c] of Object.entries(policy.countries)) out.push(`  ${s(code)}: ${s(c.input)},`);
out.push('};', '', '/// maternityPolicy.countries[code].sources (url, originalUrl?, archivedAt?).');
out.push('const Map<String, List<({String url, String? originalUrl, String? archivedAt})>> kMaternityCountrySources = {');
for (const [code, c] of Object.entries(policy.countries)) {
  out.push(`  ${s(code)}: [`);
  for (const src of c.sources) {
    out.push(`    (url: ${s(src.url)}, originalUrl: ${src.originalUrl ? s(src.originalUrl) : 'null'}, archivedAt: ${src.archivedAt ? s(src.archivedAt) : 'null'}),`);
  }
  out.push('  ],');
}
out.push('};', '');

const target = path.join(root, 'app/lib/features/tools/maternity/maternity_copy.g.dart');
const text = out.join('\n');
if (process.argv.includes('--check')) {
  if (fs.readFileSync(target, 'utf8') !== text) {
    console.error('maternity_copy.g.dart is stale');
    process.exit(1);
  }
} else {
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, text);
  console.log(`wrote ${target} (${text.length} bytes)`);
}
